(() => {
  'use strict'

  const SUPPORTED = ['pt', 'en', 'fr', 'es', 'de', 'it', 'zh', 'ja', 'ru', 'nl', 'pl']

  const texts = {
    pt: {
      pageTitle: 'Informação Legal e privacidade · 691 Lisboa', meta: 'Informação Legal, privacidade, reclamações e resolução alternativa de litígios do serviço 691 Lisboa.', back: '← Voltar ao 691 Lisboa', legalTitle: 'Informação Legal', updated: 'Última atualização: 18 de agosto de 2026', translationNote: '', providerTitle: 'Identificação do prestador', nifLabel: 'NIF', licenseLabel: 'Alvará de táxi n.º', phoneLabel: 'Telefone', mobileCall: 'Chamada para a rede móvel nacional', emailLabel: 'Email', bookingPriceTitle: 'Reservas e preço', bookingRequest: 'O envio do formulário em 691.pt constitui um pedido de reserva. A reserva fica sujeita à confirmação pelo serviço.', price: 'O preço da viagem é determinado pelo taxímetro, de acordo com o tarifário legal em vigor e as regras aplicáveis ao serviço de táxi. O valor final é o indicado pelo taxímetro no final da viagem, salvo as situações previstas na legislação aplicável.', important: 'Nota importante:', priceNote: 'as plataformas eletrónicas de serviços de táxi estão sujeitas a regras específicas sobre disponibilização de estimativas do preço final. A implementação de uma estimativa automática no formulário depende da integração do tarifário aplicável e dos parâmetros necessários para o cálculo.', privacyTitle: 'Política de privacidade', controller: 'O responsável pelo tratamento dos dados pessoais recolhidos através de 691.pt é José Alfredo Mendes Fernandes.', dataTitle: 'Dados tratados', dataText: 'Consoante a utilização do serviço, podem ser tratados nome, telefone, data e hora pretendidas, local de recolha, destino e identificadores técnicos necessários à sessão, e informação relacionada com a reserva.', purposesTitle: 'Finalidades', purpose1: 'receber e gerir pedidos de reserva;', purpose2: 'contactar o cliente relativamente à reserva;', purpose3: 'acompanhar o estado da reserva e prestar o serviço;', purpose4: 'cumprir obrigações legais e responder a reclamações ou pedidos legítimos.', basisTitle: 'Fundamento', basisText: 'Quando o tratamento é necessário para tratar e executar o pedido de serviço, o fundamento é, em regra, a execução de medidas pré-contratuais ou do contrato. Outros tratamentos dependem do respetivo fundamento legal aplicável. O consentimento não é utilizado como fundamento universal para os tratamentos necessários à prestação do serviço.', recipientsTitle: 'Destinatários e prestadores técnicos', recipientsText: 'Podem ser utilizados prestadores técnicos necessários ao funcionamento do serviço, incluindo alojamento, base de dados, mapas/geocodificação e comunicações. Esses prestadores só devem tratar dados na medida necessária às funções que lhes estão atribuídas.', mapData: 'Pesquisa de moradas: pode utilizar a API TomTom Search. Dados cartográficos do mapa de fundo: © OpenStreetMap contributors; cartografia CARTO baseada em OpenStreetMap.', retentionTitle: 'Conservação', retentionText: 'Os dados da reserva são mantidos nos sistemas operacionais ativos até à conclusão ou cancelamento da viagem e durante o curto período técnico necessário ao encerramento da sessão, após o qual a reserva é removida da base operacional. Comunicações transacionais e registos técnicos dos prestadores podem estar sujeitos aos respetivos períodos de retenção. Mantêm-se ainda os dados que, por obrigação legal, faturação, contabilidade, reclamação ou defesa de direitos, tenham de ser conservados pelo período legalmente aplicável. Dados técnicos de Push podem ser eliminados quando deixam de ser necessários ou quando a subscrição é inválida.', rightsTitle: 'Direitos', rightsText: 'O titular pode solicitar acesso, retificação, apagamento, limitação, oposição e portabilidade, quando legalmente aplicáveis, através de jose@79.pt. O exercício de direitos é, em regra, gratuito. A CNPD confirma estes direitos e a necessidade de informar os titulares sobre finalidades, categorias de dados, destinatários e conservação.', rightsLink: 'Saiba mais na CNPD', privacyComplaintsTitle: 'Reclamações sobre proteção de dados', privacyComplaintsText: 'Sem prejuízo de contactar o responsável pelo tratamento, o titular pode apresentar reclamação à', cnpdLink: 'Comissão Nacional de Proteção de Dados (CNPD)', pushTitle: 'Notificações Push', pushText: 'As notificações Push só são ativadas após autorização do utilizador. A subscrição técnica é utilizada exclusivamente para enviar atualizações relacionadas com a reserva e pode ser removida quando deixa de ser válida.', complaintsTitle: 'Livro de Reclamações', complaintsIntro: 'O acesso ao formato eletrónico do Livro de Reclamações está disponível em:', complaintsLink: 'Livro de Reclamações Eletrónico', complaintsLawText: 'O regime aplicável exige a divulgação do acesso à Plataforma Digital nos sítios da Internet de prestadores abrangidos.', complaintsLawLink: 'Decreto-Lei n.º 156/2005', ralTitle: 'Resolução Alternativa de Litígios', ralText: 'Para conflitos de consumo abrangidos pela sua competência, pode ser utilizado o Centro de Arbitragem de Conflitos de Consumo de Lisboa (CACCL), quando reunidas as condições legais, incluindo contratos de consumo celebrados e executados na Área Metropolitana de Lisboa e valor até 5.000 €.', ralLink: 'Centro de Arbitragem de Conflitos de Consumo de Lisboa', ralNote: 'O CACCL informa também sobre os respetivos formulários de informação e reclamação e meios de contacto.', contactsTitle: 'Contactos'
    },
    en: {
      pageTitle: 'Legal Information and Privacy · 691 Lisboa', meta: 'Legal information, privacy, complaints and alternative dispute resolution for the 691 Lisboa service.', back: '← Back to 691 Lisboa', legalTitle: 'Legal Information', updated: 'Last updated: 18 August 2026', translationNote: 'This translation is provided for convenience. In case of discrepancy, the Portuguese version prevails.', providerTitle: 'Service provider identification', nifLabel: 'Tax ID (NIF)', licenseLabel: 'Taxi licence no.', phoneLabel: 'Phone', mobileCall: 'Call to the Portuguese national mobile network', emailLabel: 'Email', bookingPriceTitle: 'Bookings and price', bookingRequest: 'Submitting the form on 691.pt constitutes a booking request. The booking is subject to confirmation by the service.', price: 'The trip price is determined by the taximeter, in accordance with the legal tariff in force and the rules applicable to taxi services. The final amount is the amount shown by the taximeter at the end of the trip, except where applicable law provides otherwise.', important: 'Important note:', priceNote: 'electronic taxi service platforms are subject to specific rules on providing an estimate of the final price. Implementing an automatic estimate in the form depends on integrating the applicable tariff and the parameters required for the calculation.', privacyTitle: 'Privacy policy', controller: 'The controller of personal data collected through 691.pt is José Alfredo Mendes Fernandes.', dataTitle: 'Data processed', dataText: 'Depending on how the service is used, the data processed may include name, phone number, requested date and time, pickup location, destination, technical identifiers required for the session, and booking-related information.', purposesTitle: 'Purposes', purpose1: 'receive and manage booking requests;', purpose2: 'contact the customer regarding the booking;', purpose3: 'track the booking status and provide the service;', purpose4: 'comply with legal obligations and respond to complaints or legitimate requests.', basisTitle: 'Legal basis', basisText: 'Where processing is necessary to handle and perform the requested service, the legal basis is generally the performance of pre-contractual measures or the contract. Other processing depends on the applicable legal basis. Consent is not used as a universal legal basis for processing necessary to provide the service.', recipientsTitle: 'Recipients and technical providers', recipientsText: 'Technical providers necessary to operate the service may be used, including hosting, database, mapping/geocoding and communications providers. These providers should process data only to the extent necessary for the functions assigned to them.', mapData: 'Address search may use the TomTom Search API. Background map data: © OpenStreetMap contributors; CARTO cartography based on OpenStreetMap.', retentionTitle: 'Retention', retentionText: 'Booking data is kept in active operational systems until the trip is completed or cancelled and for the short technical period required to close the session, after which the booking is removed from the operational database. Transactional communications and technical provider logs may be subject to the providers’ own retention periods. Data that must be retained for legal obligations, billing, accounting, complaints or the defence of legal rights is retained for the legally applicable period. Technical Push data may be deleted when no longer required or when the subscription becomes invalid.', rightsTitle: 'Rights', rightsText: 'The data subject may request access, rectification, erasure, restriction, objection and portability, where legally applicable, by contacting jose@79.pt. Exercising these rights is generally free of charge. The CNPD confirms these rights and the requirement to inform data subjects about purposes, data categories, recipients and retention.', rightsLink: 'Learn more at the CNPD', privacyComplaintsTitle: 'Data protection complaints', privacyComplaintsText: 'Without prejudice to contacting the controller, the data subject may lodge a complaint with the', cnpdLink: 'Portuguese Data Protection Authority (CNPD)', pushTitle: 'Push notifications', pushText: 'Push notifications are enabled only after user permission. The technical subscription is used exclusively to send booking-related updates and may be removed when it is no longer valid.', complaintsTitle: 'Complaints Book', complaintsIntro: 'The electronic Complaints Book is available at:', complaintsLink: 'Electronic Complaints Book', complaintsLawText: 'The applicable regime requires covered service providers to publish access to the Digital Platform on their websites.', complaintsLawLink: 'Decree-Law no. 156/2005', ralTitle: 'Alternative Dispute Resolution', ralText: 'For consumer disputes within its jurisdiction, the Lisbon Consumer Dispute Arbitration Centre (CACCL) may be used when the legal conditions are met, including consumer contracts concluded and performed in the Lisbon Metropolitan Area and a value of up to €5,000.', ralLink: 'Lisbon Consumer Dispute Arbitration Centre', ralNote: 'CACCL also provides information about its information and complaint forms and contact channels.', contactsTitle: 'Contacts'
    },
    fr: {
      pageTitle: 'Informations légales et confidentialité · 691 Lisboa', meta: 'Informations légales, confidentialité, réclamations et règlement extrajudiciaire des litiges du service 691 Lisboa.', back: '← Retour à 691 Lisboa', legalTitle: 'Informations légales', updated: 'Dernière mise à jour : 18 août 2026', translationNote: 'Cette traduction est fournie pour faciliter la lecture. En cas de divergence, la version portugaise prévaut.', providerTitle: 'Identification du prestataire', nifLabel: 'NIF', licenseLabel: 'Licence de taxi n°', phoneLabel: 'Téléphone', mobileCall: 'Appel vers le réseau mobile national portugais', emailLabel: 'E-mail', bookingPriceTitle: 'Réservations et prix', bookingRequest: 'L’envoi du formulaire sur 691.pt constitue une demande de réservation. La réservation reste soumise à la confirmation du service.', price: 'Le prix du trajet est déterminé par le taximètre, conformément au tarif légal en vigueur et aux règles applicables au service de taxi. Le montant final est celui indiqué par le taximètre à la fin du trajet, sauf disposition légale contraire.', important: 'Note importante :', priceNote: 'les plateformes électroniques de services de taxi sont soumises à des règles spécifiques concernant la mise à disposition d’une estimation du prix final. La mise en œuvre d’une estimation automatique dans le formulaire dépend de l’intégration du tarif applicable et des paramètres nécessaires au calcul.', privacyTitle: 'Politique de confidentialité', controller: 'Le responsable du traitement des données personnelles collectées via 691.pt est José Alfredo Mendes Fernandes.', dataTitle: 'Données traitées', dataText: 'Selon l’utilisation du service, les données traitées peuvent comprendre le nom, le téléphone, la date et l’heure souhaitées, le lieu de prise en charge, la destination, les identifiants techniques nécessaires à la session et les informations liées à la réservation.', purposesTitle: 'Finalités', purpose1: 'recevoir et gérer les demandes de réservation ;', purpose2: 'contacter le client au sujet de la réservation ;', purpose3: 'suivre l’état de la réservation et fournir le service ;', purpose4: 'respecter les obligations légales et répondre aux réclamations ou demandes légitimes.', basisTitle: 'Base juridique', basisText: 'Lorsque le traitement est nécessaire pour traiter et exécuter la demande de service, sa base juridique est, en règle générale, l’exécution de mesures précontractuelles ou du contrat. Les autres traitements reposent sur la base juridique applicable. Le consentement n’est pas utilisé comme fondement universel des traitements nécessaires à la prestation du service.', recipientsTitle: 'Destinataires et prestataires techniques', recipientsText: 'Des prestataires techniques nécessaires au fonctionnement du service peuvent être utilisés, notamment pour l’hébergement, la base de données, la cartographie/géocodification et les communications. Ces prestataires ne doivent traiter les données que dans la mesure nécessaire aux fonctions qui leur sont confiées.', mapData: 'La recherche d’adresses peut utiliser l’API TomTom Search. Données cartographiques du fond de carte : © contributeurs OpenStreetMap ; cartographie CARTO basée sur OpenStreetMap.', retentionTitle: 'Conservation', retentionText: 'Les données de réservation sont conservées dans les systèmes opérationnels actifs jusqu’à la fin ou l’annulation du trajet et pendant la courte période technique nécessaire à la fermeture de la session, après quoi la réservation est supprimée de la base opérationnelle. Les communications transactionnelles et les journaux techniques des prestataires peuvent être soumis à leurs propres durées de conservation. Les données devant être conservées pour des obligations légales, la facturation, la comptabilité, une réclamation ou la défense de droits sont conservées pendant la durée légalement applicable. Les données techniques Push peuvent être supprimées lorsqu’elles ne sont plus nécessaires ou lorsque l’abonnement devient invalide.', rightsTitle: 'Droits', rightsText: 'La personne concernée peut demander l’accès, la rectification, l’effacement, la limitation, l’opposition et la portabilité, lorsque ces droits sont légalement applicables, via jose@79.pt. L’exercice de ces droits est en principe gratuit. La CNPD confirme ces droits et l’obligation d’informer les personnes concernées sur les finalités, les catégories de données, les destinataires et la conservation.', rightsLink: 'En savoir plus auprès de la CNPD', privacyComplaintsTitle: 'Réclamations relatives à la protection des données', privacyComplaintsText: 'Sans préjudice de la possibilité de contacter le responsable du traitement, la personne concernée peut déposer une réclamation auprès de la', cnpdLink: 'Commission nationale de protection des données (CNPD)', pushTitle: 'Notifications Push', pushText: 'Les notifications Push ne sont activées qu’après l’autorisation de l’utilisateur. L’abonnement technique est utilisé exclusivement pour envoyer des mises à jour liées à la réservation et peut être supprimé lorsqu’il n’est plus valide.', complaintsTitle: 'Livre de réclamations', complaintsIntro: 'Le Livre de réclamations électronique est disponible à l’adresse suivante :', complaintsLink: 'Livre de réclamations électronique', complaintsLawText: 'Le régime applicable impose aux prestataires concernés de publier sur leur site l’accès à la Plateforme numérique.', complaintsLawLink: 'Décret-loi n° 156/2005', ralTitle: 'Règlement extrajudiciaire des litiges', ralText: 'Pour les litiges de consommation relevant de sa compétence, le Centre d’arbitrage des litiges de consommation de Lisbonne (CACCL) peut être utilisé lorsque les conditions légales sont réunies, notamment pour les contrats de consommation conclus et exécutés dans l’aire métropolitaine de Lisbonne et d’une valeur maximale de 5 000 €.', ralLink: 'Centre d’arbitrage des litiges de consommation de Lisbonne', ralNote: 'Le CACCL fournit également des informations sur ses formulaires d’information et de réclamation ainsi que sur ses moyens de contact.', contactsTitle: 'Contacts'
    },
    es: {
      pageTitle: 'Información Legal y privacidad · 691 Lisboa', meta: 'Información legal, privacidad, reclamaciones y resolución alternativa de litigios del servicio 691 Lisboa.', back: '← Volver a 691 Lisboa', legalTitle: 'Información Legal', updated: 'Última actualización: 18 de agosto de 2026', translationNote: 'Esta traducción se facilita para ayudar a la lectura. En caso de discrepancia, prevalece la versión portuguesa.', providerTitle: 'Identificación del prestador', nifLabel: 'NIF', licenseLabel: 'Licencia de taxi n.º', phoneLabel: 'Teléfono', mobileCall: 'Llamada a la red móvil nacional portuguesa', emailLabel: 'Correo electrónico', bookingPriceTitle: 'Reservas y precio', bookingRequest: 'El envío del formulario en 691.pt constituye una solicitud de reserva. La reserva queda sujeta a confirmación por parte del servicio.', price: 'El precio del viaje se determina mediante taxímetro, de acuerdo con la tarifa legal vigente y las normas aplicables al servicio de taxi. El importe final es el indicado por el taxímetro al finalizar el viaje, salvo las situaciones previstas en la legislación aplicable.', important: 'Nota importante:', priceNote: 'las plataformas electrónicas de servicios de taxi están sujetas a normas específicas sobre la disponibilidad de una estimación del precio final. La implementación de una estimación automática en el formulario depende de la integración de la tarifa aplicable y de los parámetros necesarios para el cálculo.', privacyTitle: 'Política de privacidad', controller: 'El responsable del tratamiento de los datos personales recogidos a través de 691.pt es José Alfredo Mendes Fernandes.', dataTitle: 'Datos tratados', dataText: 'Según el uso del servicio, pueden tratarse el nombre, teléfono, fecha y hora solicitadas, lugar de recogida, destino, identificadores técnicos necesarios para la sesión e información relacionada con la reserva.', purposesTitle: 'Finalidades', purpose1: 'recibir y gestionar solicitudes de reserva;', purpose2: 'contactar con el cliente en relación con la reserva;', purpose3: 'seguir el estado de la reserva y prestar el servicio;', purpose4: 'cumplir obligaciones legales y responder a reclamaciones o solicitudes legítimas.', basisTitle: 'Base jurídica', basisText: 'Cuando el tratamiento es necesario para gestionar y ejecutar la solicitud del servicio, la base jurídica es, por regla general, la ejecución de medidas precontractuales o del contrato. Otros tratamientos dependen de la base jurídica aplicable. El consentimiento no se utiliza como fundamento universal para los tratamientos necesarios para prestar el servicio.', recipientsTitle: 'Destinatarios y proveedores técnicos', recipientsText: 'Pueden utilizarse proveedores técnicos necesarios para el funcionamiento del servicio, incluidos alojamiento, base de datos, mapas/geocodificación y comunicaciones. Estos proveedores solo deben tratar datos en la medida necesaria para las funciones que tengan asignadas.', mapData: 'La búsqueda de direcciones puede utilizar la API TomTom Search. Datos cartográficos del mapa de fondo: © colaboradores de OpenStreetMap; cartografía CARTO basada en OpenStreetMap.', retentionTitle: 'Conservación', retentionText: 'Los datos de la reserva se mantienen en los sistemas operativos activos hasta la finalización o cancelación del viaje y durante el breve período técnico necesario para cerrar la sesión, tras lo cual la reserva se elimina de la base operativa. Las comunicaciones transaccionales y los registros técnicos de los proveedores pueden estar sujetos a sus propios períodos de conservación. Los datos que deban conservarse por obligaciones legales, facturación, contabilidad, reclamaciones o defensa de derechos se conservarán durante el período legalmente aplicable. Los datos técnicos de Push pueden eliminarse cuando dejen de ser necesarios o cuando la suscripción sea inválida.', rightsTitle: 'Derechos', rightsText: 'El interesado puede solicitar acceso, rectificación, supresión, limitación, oposición y portabilidad, cuando sean legalmente aplicables, a través de jose@79.pt. El ejercicio de los derechos es, por regla general, gratuito. La CNPD confirma estos derechos y la necesidad de informar a los interesados sobre las finalidades, categorías de datos, destinatarios y conservación.', rightsLink: 'Más información en la CNPD', privacyComplaintsTitle: 'Reclamaciones sobre protección de datos', privacyComplaintsText: 'Sin perjuicio de contactar con el responsable del tratamiento, el interesado puede presentar una reclamación ante la', cnpdLink: 'Comisión Nacional de Protección de Datos (CNPD)', pushTitle: 'Notificaciones Push', pushText: 'Las notificaciones Push solo se activan tras la autorización del usuario. La suscripción técnica se utiliza exclusivamente para enviar actualizaciones relacionadas con la reserva y puede eliminarse cuando deje de ser válida.', complaintsTitle: 'Libro de Reclamaciones', complaintsIntro: 'El formato electrónico del Libro de Reclamaciones está disponible en:', complaintsLink: 'Libro de Reclamaciones Electrónico', complaintsLawText: 'El régimen aplicable exige a los prestadores incluidos publicar en sus sitios web el acceso a la Plataforma Digital.', complaintsLawLink: 'Decreto-Ley n.º 156/2005', ralTitle: 'Resolución Alternativa de Litigios', ralText: 'Para los conflictos de consumo comprendidos en su competencia, puede utilizarse el Centro de Arbitraje de Conflictos de Consumo de Lisboa (CACCL) cuando se cumplan las condiciones legales, incluidos contratos de consumo celebrados y ejecutados en el Área Metropolitana de Lisboa y con un valor de hasta 5.000 €.', ralLink: 'Centro de Arbitraje de Conflictos de Consumo de Lisboa', ralNote: 'El CACCL también informa sobre sus formularios de información y reclamación y sus medios de contacto.', contactsTitle: 'Contactos'
    },
    de: {
      pageTitle: 'Rechtliche Informationen und Datenschutz · 691 Lisboa', meta: 'Rechtliche Informationen, Datenschutz, Beschwerden und alternative Streitbeilegung für den Dienst 691 Lisboa.', back: '← Zurück zu 691 Lisboa', legalTitle: 'Rechtliche Informationen', updated: 'Letzte Aktualisierung: 18. August 2026', translationNote: 'Diese Übersetzung dient der besseren Lesbarkeit. Bei Abweichungen ist die portugiesische Fassung maßgeblich.', providerTitle: 'Angaben zum Dienstleister', nifLabel: 'Steuernummer (NIF)', licenseLabel: 'Taxi-Lizenz Nr.', phoneLabel: 'Telefon', mobileCall: 'Anruf in das portugiesische nationale Mobilfunknetz', emailLabel: 'E-Mail', bookingPriceTitle: 'Buchungen und Preis', bookingRequest: 'Das Absenden des Formulars auf 691.pt stellt eine Buchungsanfrage dar. Die Buchung bedarf der Bestätigung durch den Dienst.', price: 'Der Fahrpreis wird vom Taxameter gemäß dem geltenden gesetzlichen Tarif und den für Taxidienste geltenden Regeln bestimmt. Maßgeblich ist der am Ende der Fahrt vom Taxameter angezeigte Betrag, soweit das anwendbare Recht nichts anderes vorsieht.', important: 'Wichtiger Hinweis:', priceNote: 'elektronische Taxidienst-Plattformen unterliegen besonderen Regeln zur Bereitstellung einer Schätzung des Endpreises. Eine automatische Schätzung im Formular setzt die Einbindung des anwendbaren Tarifs und der für die Berechnung erforderlichen Parameter voraus.', privacyTitle: 'Datenschutzerklärung', controller: 'Verantwortlicher für die über 691.pt erhobenen personenbezogenen Daten ist José Alfredo Mendes Fernandes.', dataTitle: 'Verarbeitete Daten', dataText: 'Je nach Nutzung des Dienstes können Name, Telefonnummer, gewünschtes Datum und Uhrzeit, Abholort, Ziel, für die Sitzung erforderliche technische Kennungen und buchungsbezogene Informationen verarbeitet werden.', purposesTitle: 'Zwecke', purpose1: 'Buchungsanfragen entgegennehmen und verwalten;', purpose2: 'den Kunden zur Buchung kontaktieren;', purpose3: 'den Buchungsstatus verfolgen und den Dienst erbringen;', purpose4: 'gesetzliche Pflichten erfüllen und auf Beschwerden oder berechtigte Anfragen reagieren.', basisTitle: 'Rechtsgrundlage', basisText: 'Soweit die Verarbeitung für die Bearbeitung und Durchführung der Dienstleistungsanfrage erforderlich ist, beruht sie grundsätzlich auf vorvertraglichen Maßnahmen oder der Vertragserfüllung. Andere Verarbeitungen richten sich nach der jeweils anwendbaren Rechtsgrundlage. Einwilligung wird nicht als universelle Grundlage für Verarbeitungen verwendet, die zur Erbringung des Dienstes erforderlich sind.', recipientsTitle: 'Empfänger und technische Dienstleister', recipientsText: 'Für den Betrieb des Dienstes erforderliche technische Anbieter können eingesetzt werden, darunter Hosting-, Datenbank-, Karten-/Geokodierungs- und Kommunikationsanbieter. Diese Anbieter sollen Daten nur in dem Umfang verarbeiten, der für die ihnen übertragenen Aufgaben erforderlich ist.', mapData: 'Die Adresssuche kann die TomTom Search API verwenden. Kartendaten der Hintergrundkarte: © OpenStreetMap-Mitwirkende; CARTO-Kartografie auf Grundlage von OpenStreetMap.', retentionTitle: 'Speicherdauer', retentionText: 'Buchungsdaten werden in den aktiven Betriebssystemen bis zum Abschluss oder zur Stornierung der Fahrt und für den kurzen technischen Zeitraum zur Beendigung der Sitzung gespeichert; anschließend wird die Buchung aus der operativen Datenbank entfernt. Transaktionskommunikation und technische Protokolle der Anbieter können deren eigenen Aufbewahrungsfristen unterliegen. Daten, die aufgrund gesetzlicher Pflichten, Rechnungsstellung, Buchhaltung, Beschwerden oder Rechtsverteidigung aufbewahrt werden müssen, bleiben für den gesetzlich vorgeschriebenen Zeitraum gespeichert. Technische Push-Daten können gelöscht werden, wenn sie nicht mehr erforderlich oder die Subscription ungültig ist.', rightsTitle: 'Rechte', rightsText: 'Die betroffene Person kann, soweit gesetzlich anwendbar, über jose@79.pt Auskunft, Berichtigung, Löschung, Einschränkung, Widerspruch und Datenübertragbarkeit verlangen. Die Ausübung dieser Rechte ist grundsätzlich kostenlos. Die CNPD bestätigt diese Rechte und die Pflicht, betroffene Personen über Zwecke, Datenkategorien, Empfänger und Speicherdauer zu informieren.', rightsLink: 'Mehr bei der CNPD', privacyComplaintsTitle: 'Datenschutzbeschwerden', privacyComplaintsText: 'Unbeschadet einer Kontaktaufnahme mit dem Verantwortlichen kann die betroffene Person Beschwerde einlegen bei der', cnpdLink: 'Portugiesischen Datenschutzbehörde (CNPD)', pushTitle: 'Push-Benachrichtigungen', pushText: 'Push-Benachrichtigungen werden nur nach Zustimmung des Nutzers aktiviert. Die technische Subscription wird ausschließlich für buchungsbezogene Aktualisierungen verwendet und kann entfernt werden, wenn sie nicht mehr gültig ist.', complaintsTitle: 'Beschwerdebuch', complaintsIntro: 'Das elektronische Beschwerdebuch ist verfügbar unter:', complaintsLink: 'Elektronisches Beschwerdebuch', complaintsLawText: 'Die geltende Regelung verpflichtet erfasste Anbieter, auf ihren Websites den Zugang zur Digitalen Plattform zu veröffentlichen.', complaintsLawLink: 'Gesetzesdekret Nr. 156/2005', ralTitle: 'Alternative Streitbeilegung', ralText: 'Für Verbraucherstreitigkeiten in seinem Zuständigkeitsbereich kann das Lissaboner Zentrum für die Schlichtung von Verbraucherstreitigkeiten (CACCL) genutzt werden, wenn die gesetzlichen Voraussetzungen erfüllt sind, darunter in der Metropolregion Lissabon geschlossene und erfüllte Verbraucherverträge mit einem Wert bis 5.000 €.', ralLink: 'Lissaboner Zentrum für die Schlichtung von Verbraucherstreitigkeiten', ralNote: 'Das CACCL informiert außerdem über seine Informations- und Beschwerdeformulare sowie Kontaktmöglichkeiten.', contactsTitle: 'Kontakte'
    },
    it: {
      pageTitle: 'Informazioni Legali e privacy · 691 Lisboa', meta: 'Informazioni legali, privacy, reclami e risoluzione alternativa delle controversie del servizio 691 Lisboa.', back: '← Torna a 691 Lisboa', legalTitle: 'Informazioni Legali', updated: 'Ultimo aggiornamento: 18 agosto 2026', translationNote: 'Questa traduzione è fornita per agevolare la lettura. In caso di divergenze prevale la versione portoghese.', providerTitle: 'Identificazione del prestatore', nifLabel: 'NIF', licenseLabel: 'Licenza taxi n.', phoneLabel: 'Telefono', mobileCall: 'Chiamata verso la rete mobile nazionale portoghese', emailLabel: 'Email', bookingPriceTitle: 'Prenotazioni e prezzo', bookingRequest: 'L’invio del modulo su 691.pt costituisce una richiesta di prenotazione. La prenotazione è soggetta alla conferma del servizio.', price: 'Il prezzo del viaggio è determinato dal tassametro, in conformità alla tariffa legale in vigore e alle norme applicabili al servizio taxi. L’importo finale è quello indicato dal tassametro al termine del viaggio, salvo i casi previsti dalla normativa applicabile.', important: 'Nota importante:', priceNote: 'le piattaforme elettroniche di servizi taxi sono soggette a regole specifiche sulla disponibilità di una stima del prezzo finale. L’implementazione di una stima automatica nel modulo dipende dall’integrazione della tariffa applicabile e dei parametri necessari al calcolo.', privacyTitle: 'Informativa sulla privacy', controller: 'Il titolare del trattamento dei dati personali raccolti tramite 691.pt è José Alfredo Mendes Fernandes.', dataTitle: 'Dati trattati', dataText: 'A seconda dell’utilizzo del servizio, possono essere trattati nome, telefono, data e ora richieste, luogo di ritiro, destinazione, identificatori tecnici necessari alla sessione e informazioni relative alla prenotazione.', purposesTitle: 'Finalità', purpose1: 'ricevere e gestire le richieste di prenotazione;', purpose2: 'contattare il cliente in merito alla prenotazione;', purpose3: 'seguire lo stato della prenotazione e fornire il servizio;', purpose4: 'adempiere agli obblighi di legge e rispondere a reclami o richieste legittime.', basisTitle: 'Base giuridica', basisText: 'Quando il trattamento è necessario per gestire ed eseguire la richiesta di servizio, la base giuridica è, di regola, l’esecuzione di misure precontrattuali o del contratto. Gli altri trattamenti dipendono dalla relativa base giuridica applicabile. Il consenso non viene utilizzato come base universale per i trattamenti necessari alla prestazione del servizio.', recipientsTitle: 'Destinatari e fornitori tecnici', recipientsText: 'Possono essere utilizzati fornitori tecnici necessari al funzionamento del servizio, inclusi hosting, database, mappe/geocodifica e comunicazioni. Tali fornitori devono trattare i dati solo nella misura necessaria alle funzioni loro affidate.', mapData: 'La ricerca degli indirizzi può utilizzare l’API TomTom Search. Dati cartografici della mappa di sfondo: © collaboratori OpenStreetMap; cartografia CARTO basata su OpenStreetMap.', retentionTitle: 'Conservazione', retentionText: 'I dati della prenotazione sono mantenuti nei sistemi operativi attivi fino al completamento o alla cancellazione del viaggio e per il breve periodo tecnico necessario alla chiusura della sessione, dopodiché la prenotazione viene rimossa dal database operativo. Le comunicazioni transazionali e i registri tecnici dei fornitori possono essere soggetti ai rispettivi periodi di conservazione. I dati che devono essere conservati per obblighi di legge, fatturazione, contabilità, reclami o difesa di diritti sono mantenuti per il periodo legalmente applicabile. I dati tecnici Push possono essere eliminati quando non sono più necessari o quando la sottoscrizione non è valida.', rightsTitle: 'Diritti', rightsText: 'L’interessato può richiedere accesso, rettifica, cancellazione, limitazione, opposizione e portabilità, quando legalmente applicabili, tramite jose@79.pt. L’esercizio dei diritti è, di regola, gratuito. La CNPD conferma tali diritti e la necessità di informare gli interessati su finalità, categorie di dati, destinatari e conservazione.', rightsLink: 'Maggiori informazioni presso la CNPD', privacyComplaintsTitle: 'Reclami sulla protezione dei dati', privacyComplaintsText: 'Fermo restando il contatto con il titolare del trattamento, l’interessato può presentare un reclamo alla', cnpdLink: 'Commissione nazionale portoghese per la protezione dei dati (CNPD)', pushTitle: 'Notifiche Push', pushText: 'Le notifiche Push vengono attivate solo dopo l’autorizzazione dell’utente. La sottoscrizione tecnica è utilizzata esclusivamente per inviare aggiornamenti relativi alla prenotazione e può essere rimossa quando non è più valida.', complaintsTitle: 'Libro dei Reclami', complaintsIntro: 'Il Libro dei Reclami elettronico è disponibile su:', complaintsLink: 'Libro dei Reclami Elettronico', complaintsLawText: 'Il regime applicabile impone ai prestatori interessati di pubblicare sui propri siti l’accesso alla Piattaforma Digitale.', complaintsLawLink: 'Decreto-Legge n. 156/2005', ralTitle: 'Risoluzione Alternativa delle Controversie', ralText: 'Per le controversie dei consumatori rientranti nella sua competenza, può essere utilizzato il Centro di Arbitrato delle Controversie dei Consumatori di Lisbona (CACCL) quando sono soddisfatte le condizioni di legge, compresi i contratti di consumo conclusi ed eseguiti nell’Area Metropolitana di Lisbona e di valore fino a 5.000 €.', ralLink: 'Centro di Arbitrato delle Controversie dei Consumatori di Lisbona', ralNote: 'Il CACCL fornisce inoltre informazioni sui propri moduli informativi e di reclamo e sui canali di contatto.', contactsTitle: 'Contatti'
    },
    zh: {
      pageTitle: '法律信息与隐私 · 691 Lisboa', meta: '691 Lisboa 服务的法律信息、隐私、投诉和替代性争议解决信息。', back: '← 返回 691 Lisboa', legalTitle: '法律信息', updated: '最后更新：2026年8月18日', translationNote: '本翻译仅为方便阅读。如有差异，以葡萄牙语版本为准。', providerTitle: '服务提供者信息', nifLabel: '税号（NIF）', licenseLabel: '出租车许可证编号', phoneLabel: '电话', mobileCall: '拨打葡萄牙国内移动网络', emailLabel: '电子邮件', bookingPriceTitle: '预订与价格', bookingRequest: '在 691.pt 提交表单即构成预订请求。预订须经本服务确认。', price: '行程价格由计价器根据现行法定费率及适用于出租车服务的规则确定。除适用法律另有规定外，最终金额以行程结束时计价器显示的金额为准。', important: '重要说明：', priceNote: '电子出租车服务平台须遵守关于提供最终价格估算的特定规则。表单中的自动估价功能需要接入适用费率及计算所需参数后方可实施。', privacyTitle: '隐私政策', controller: '通过 691.pt 收集的个人数据的控制者为 José Alfredo Mendes Fernandes。', dataTitle: '处理的数据', dataText: '根据服务使用方式，可能处理姓名、电话号码、所需日期和时间、上车地点、目的地、会话所需的技术标识符以及与预订有关的信息。', purposesTitle: '处理目的', purpose1: '接收和管理预订请求；', purpose2: '就预订事项联系客户；', purpose3: '跟踪预订状态并提供服务；', purpose4: '履行法律义务并处理投诉或合法请求。', basisTitle: '法律依据', basisText: '当处理数据是为办理和执行服务请求所必需时，其法律依据通常为履行合同前措施或合同。其他处理活动取决于相应适用的法律依据。对于提供服务所必需的处理，不会将同意作为普遍适用的法律依据。', recipientsTitle: '接收方与技术服务商', recipientsText: '服务运行可能会使用必要的技术服务提供商，包括托管、数据库、地图/地理编码和通信服务商。这些服务商仅应在履行所承担功能所必需的范围内处理数据。', mapData: '地址搜索可能使用 TomTom Search API。背景地图数据：© OpenStreetMap 贡献者；基于 OpenStreetMap 的 CARTO 制图。', retentionTitle: '保存期限', retentionText: '预订数据会保存在活动运营系统中，直至行程完成或取消，并在关闭会话所需的短暂技术期限内继续保留，之后将从运营数据库中删除。交易通信和技术服务商日志可能适用各服务商自身的保存期限。因法律义务、开票、会计、投诉或权利保护而必须保存的数据，将按照适用法律规定的期限保存。Push 技术数据在不再需要或订阅失效时可被删除。', rightsTitle: '您的权利', rightsText: '在法律适用的情况下，数据主体可通过 jose@79.pt 请求访问、更正、删除、限制处理、反对处理和数据可携权。行使这些权利原则上免费。CNPD 确认这些权利以及向数据主体告知处理目的、数据类别、接收方和保存期限的义务。', rightsLink: '在 CNPD 了解更多', privacyComplaintsTitle: '数据保护投诉', privacyComplaintsText: '在不影响联系数据控制者的前提下，数据主体可向以下机构提出投诉：', cnpdLink: '葡萄牙国家数据保护委员会（CNPD）', pushTitle: 'Push 通知', pushText: '只有在用户授权后才会启用 Push 通知。技术订阅仅用于发送与预订有关的更新，并可在失效后被删除。', complaintsTitle: '投诉簿', complaintsIntro: '电子投诉簿可通过以下链接访问：', complaintsLink: '电子投诉簿', complaintsLawText: '适用制度要求受涵盖的服务提供者在其网站上公布数字平台的访问入口。', complaintsLawLink: '第156/2005号法令', ralTitle: '替代性争议解决', ralText: '对于属于其管辖范围的消费者争议，在符合法律条件时，可使用里斯本消费者争议仲裁中心（CACCL），包括在里斯本大都市区订立并履行且金额不超过5,000欧元的消费者合同。', ralLink: '里斯本消费者争议仲裁中心', ralNote: 'CACCL 还提供其信息表、投诉表及联系方式。', contactsTitle: '联系方式'
    },
    ja: {
      pageTitle: '法的情報とプライバシー · 691 Lisboa', meta: '691 Lisboa サービスの法的情報、プライバシー、苦情、裁判外紛争解決に関する情報。', back: '← 691 Lisboa に戻る', legalTitle: '法的情報', updated: '最終更新：2026年8月18日', translationNote: 'この翻訳は読みやすさのために提供されています。内容に相違がある場合はポルトガル語版が優先されます。', providerTitle: 'サービス提供者情報', nifLabel: '納税者番号（NIF）', licenseLabel: 'タクシー営業許可番号', phoneLabel: '電話', mobileCall: 'ポルトガル国内携帯電話網への通話', emailLabel: 'メール', bookingPriceTitle: '予約と料金', bookingRequest: '691.pt のフォーム送信は予約リクエストとなります。予約はサービスによる確認を条件とします。', price: '運賃は、現行の法定料金表およびタクシーサービスに適用される規則に従い、タクシーメーターによって決定されます。適用法に別段の定めがある場合を除き、最終金額は乗車終了時にメーターに表示された金額です。', important: '重要事項：', priceNote: '電子タクシーサービス・プラットフォームには、最終価格の見積りを提供することに関する特別な規則があります。フォームで自動見積りを実装するには、適用料金表と計算に必要なパラメータを組み込む必要があります。', privacyTitle: 'プライバシーポリシー', controller: '691.pt を通じて収集される個人データの管理者は José Alfredo Mendes Fernandes です。', dataTitle: '処理されるデータ', dataText: 'サービスの利用状況に応じて、氏名、電話番号、希望日時、乗車場所、目的地、セッションに必要な技術的識別子、予約に関連する情報が処理される場合があります。', purposesTitle: '利用目的', purpose1: '予約リクエストの受領および管理；', purpose2: '予約に関して顧客へ連絡すること；', purpose3: '予約状況を追跡しサービスを提供すること；', purpose4: '法的義務を履行し、苦情または正当な要請に対応すること。', basisTitle: '法的根拠', basisText: 'サービスの依頼を処理・実行するために処理が必要な場合、原則として契約前の措置または契約の履行が法的根拠となります。その他の処理は、それぞれ適用される法的根拠に基づきます。サービス提供に必要な処理について、同意を普遍的な根拠として使用することはありません。', recipientsTitle: '受領者および技術サービス提供者', recipientsText: 'サービスの運営に必要な技術提供者（ホスティング、データベース、地図／ジオコーディング、通信など）を利用する場合があります。これらの提供者は、委託された機能の遂行に必要な範囲でのみデータを処理すべきものとします。', mapData: '住所検索には TomTom Search API を使用する場合があります。背景地図データ：© OpenStreetMap contributors、OpenStreetMap に基づく CARTO の地図。', retentionTitle: '保存期間', retentionText: '予約データは、乗車の完了またはキャンセルまで、およびセッション終了に必要な短い技術的期間、稼働中の運用システムに保持され、その後運用データベースから削除されます。取引上の通信や技術サービス提供者のログには、それぞれの保存期間が適用される場合があります。法的義務、請求、会計、苦情対応、権利防御のため保存が必要なデータは、法令上必要な期間保持されます。Push の技術データは、不要になった場合または購読が無効になった場合に削除されることがあります。', rightsTitle: '権利', rightsText: '法的に適用される場合、データ主体は jose@79.pt を通じてアクセス、訂正、削除、処理制限、異議申立て、データポータビリティを請求できます。これらの権利行使は原則無料です。CNPD はこれらの権利および処理目的、データの種類、受領者、保存期間について通知する必要性を確認しています。', rightsLink: 'CNPD で詳しく見る', privacyComplaintsTitle: 'データ保護に関する苦情', privacyComplaintsText: 'データ管理者への連絡を妨げることなく、データ主体は次の機関に苦情を申し立てることができます：', cnpdLink: 'ポルトガル国家データ保護委員会（CNPD）', pushTitle: 'Push 通知', pushText: 'Push 通知は利用者の許可後にのみ有効になります。技術的な購読情報は予約に関する更新の送信だけに使用され、無効になった場合に削除されることがあります。', complaintsTitle: '苦情申立て', complaintsIntro: '電子版の苦情簿は次のリンクから利用できます：', complaintsLink: '電子苦情簿', complaintsLawText: '適用制度により、対象事業者は自社ウェブサイト上でデジタルプラットフォームへのアクセスを案内する必要があります。', complaintsLawLink: '政令第156/2005号', ralTitle: '裁判外紛争解決', ralText: '管轄対象となる消費者紛争について、法的条件を満たす場合にはリスボン消費者紛争仲裁センター（CACCL）を利用できます。これには、リスボン大都市圏で締結・履行された5,000ユーロ以下の消費者契約が含まれます。', ralLink: 'リスボン消費者紛争仲裁センター', ralNote: 'CACCL は情報・苦情フォームおよび連絡方法についても案内しています。', contactsTitle: '連絡先'
    },
    ru: {
      pageTitle: 'Правовая информация и конфиденциальность · 691 Lisboa', meta: 'Правовая информация, конфиденциальность, жалобы и альтернативное разрешение споров для сервиса 691 Lisboa.', back: '← Назад к 691 Lisboa', legalTitle: 'Правовая информация', updated: 'Последнее обновление: 18 августа 2026 г.', translationNote: 'Этот перевод предоставлен для удобства чтения. В случае расхождений преимущественную силу имеет версия на португальском языке.', providerTitle: 'Сведения о поставщике услуг', nifLabel: 'Налоговый номер (NIF)', licenseLabel: 'Лицензия такси №', phoneLabel: 'Телефон', mobileCall: 'Звонок в национальную мобильную сеть Португалии', emailLabel: 'Эл. почта', bookingPriceTitle: 'Бронирование и цена', bookingRequest: 'Отправка формы на 691.pt является запросом на бронирование. Бронирование подлежит подтверждению сервисом.', price: 'Стоимость поездки определяется таксометром в соответствии с действующим законным тарифом и правилами, применимыми к услугам такси. Окончательная сумма определяется показанием таксометра в конце поездки, если применимое законодательство не предусматривает иное.', important: 'Важное примечание:', priceNote: 'электронные платформы услуг такси подчиняются специальным правилам о предоставлении оценки итоговой цены. Автоматическая оценка в форме требует интеграции применимого тарифа и параметров, необходимых для расчёта.', privacyTitle: 'Политика конфиденциальности', controller: 'Контролёром персональных данных, собираемых через 691.pt, является José Alfredo Mendes Fernandes.', dataTitle: 'Обрабатываемые данные', dataText: 'В зависимости от использования сервиса могут обрабатываться имя, телефон, желаемые дата и время, место подачи, пункт назначения, технические идентификаторы, необходимые для сессии, и информация, связанная с бронированием.', purposesTitle: 'Цели', purpose1: 'получение и управление запросами на бронирование;', purpose2: 'связь с клиентом по вопросам бронирования;', purpose3: 'отслеживание статуса бронирования и предоставление услуги;', purpose4: 'выполнение юридических обязанностей и ответы на жалобы или законные запросы.', basisTitle: 'Правовое основание', basisText: 'Если обработка необходима для обработки и исполнения запроса на услугу, правовым основанием, как правило, является выполнение преддоговорных мер или договора. Иная обработка зависит от соответствующего применимого правового основания. Согласие не используется как универсальное основание для обработки, необходимой для оказания услуги.', recipientsTitle: 'Получатели и технические поставщики', recipientsText: 'Для работы сервиса могут использоваться необходимые технические поставщики, включая хостинг, базу данных, карты/геокодирование и коммуникации. Такие поставщики должны обрабатывать данные только в объёме, необходимом для выполнения порученных им функций.', mapData: 'Поиск адресов может использовать API TomTom Search. Данные фоновой карты: © участники OpenStreetMap; картография CARTO на основе OpenStreetMap.', retentionTitle: 'Хранение', retentionText: 'Данные бронирования хранятся в активных операционных системах до завершения или отмены поездки и в течение короткого технического периода, необходимого для закрытия сессии, после чего бронирование удаляется из операционной базы. Транзакционные сообщения и технические журналы поставщиков могут иметь собственные сроки хранения. Данные, которые необходимо хранить в силу закона, для выставления счетов, бухгалтерии, рассмотрения жалоб или защиты прав, сохраняются в течение установленного законом срока. Технические данные Push могут быть удалены, когда перестают быть необходимыми или подписка становится недействительной.', rightsTitle: 'Права', rightsText: 'Субъект данных может запросить доступ, исправление, удаление, ограничение, возражение и переносимость, если эти права применимы по закону, через jose@79.pt. Реализация прав, как правило, бесплатна. CNPD подтверждает эти права и обязанность информировать субъектов о целях, категориях данных, получателях и сроках хранения.', rightsLink: 'Подробнее на сайте CNPD', privacyComplaintsTitle: 'Жалобы по защите данных', privacyComplaintsText: 'Независимо от возможности обратиться к контролёру, субъект данных может подать жалобу в', cnpdLink: 'Национальную комиссию по защите данных Португалии (CNPD)', pushTitle: 'Push-уведомления', pushText: 'Push-уведомления включаются только после разрешения пользователя. Техническая подписка используется исключительно для отправки обновлений, связанных с бронированием, и может быть удалена, когда становится недействительной.', complaintsTitle: 'Книга жалоб', complaintsIntro: 'Электронная Книга жалоб доступна по адресу:', complaintsLink: 'Электронная Книга жалоб', complaintsLawText: 'Применимый режим требует от охваченных поставщиков публиковать на своих сайтах доступ к Цифровой платформе.', complaintsLawLink: 'Декрет-закон № 156/2005', ralTitle: 'Альтернативное разрешение споров', ralText: 'Для потребительских споров в пределах его компетенции можно использовать Лиссабонский центр арбитража потребительских споров (CACCL), если соблюдены юридические условия, включая потребительские договоры, заключённые и исполненные в Лиссабонской агломерации, стоимостью до 5 000 €.', ralLink: 'Лиссабонский центр арбитража потребительских споров', ralNote: 'CACCL также предоставляет информацию о формах для получения информации и подачи жалоб, а также о способах связи.', contactsTitle: 'Контакты'
    },
    nl: {
      pageTitle: 'Juridische informatie en privacy · 691 Lisboa', meta: 'Juridische informatie, privacy, klachten en alternatieve geschillenbeslechting voor de dienst 691 Lisboa.', back: '← Terug naar 691 Lisboa', legalTitle: 'Juridische informatie', updated: 'Laatst bijgewerkt: 18 augustus 2026', translationNote: 'Deze vertaling is bedoeld om het lezen te vergemakkelijken. Bij verschillen is de Portugese versie doorslaggevend.', providerTitle: 'Identificatie van de dienstverlener', nifLabel: 'Fiscaal nummer (NIF)', licenseLabel: 'Taxivergunning nr.', phoneLabel: 'Telefoon', mobileCall: 'Oproep naar het Portugese nationale mobiele netwerk', emailLabel: 'E-mail', bookingPriceTitle: 'Reserveringen en prijs', bookingRequest: 'Het verzenden van het formulier op 691.pt vormt een reserveringsaanvraag. De reservering is onderworpen aan bevestiging door de dienst.', price: 'De ritprijs wordt bepaald door de taximeter, overeenkomstig het geldende wettelijke tarief en de regels die op taxidiensten van toepassing zijn. Het uiteindelijke bedrag is het bedrag dat de taximeter aan het einde van de rit aangeeft, tenzij de toepasselijke wetgeving anders bepaalt.', important: 'Belangrijke opmerking:', priceNote: 'elektronische platforms voor taxidiensten zijn onderworpen aan specifieke regels over het beschikbaar stellen van een raming van de uiteindelijke prijs. Een automatische raming in het formulier vereist integratie van het toepasselijke tarief en de parameters die voor de berekening nodig zijn.', privacyTitle: 'Privacybeleid', controller: 'De verwerkingsverantwoordelijke voor persoonsgegevens die via 691.pt worden verzameld is José Alfredo Mendes Fernandes.', dataTitle: 'Verwerkte gegevens', dataText: 'Afhankelijk van het gebruik van de dienst kunnen naam, telefoonnummer, gewenste datum en tijd, ophaallocatie, bestemming, technische identificatoren die voor de sessie nodig zijn en informatie over de reservering worden verwerkt.', purposesTitle: 'Doeleinden', purpose1: 'reserveringsaanvragen ontvangen en beheren;', purpose2: 'contact opnemen met de klant over de reservering;', purpose3: 'de status van de reservering volgen en de dienst leveren;', purpose4: 'wettelijke verplichtingen naleven en reageren op klachten of legitieme verzoeken.', basisTitle: 'Rechtsgrond', basisText: 'Wanneer de verwerking nodig is om het verzoek om dienstverlening te behandelen en uit te voeren, is de rechtsgrond in de regel de uitvoering van precontractuele maatregelen of van de overeenkomst. Andere verwerkingen hangen af van de toepasselijke rechtsgrond. Toestemming wordt niet als universele grondslag gebruikt voor verwerkingen die noodzakelijk zijn voor de dienstverlening.', recipientsTitle: 'Ontvangers en technische dienstverleners', recipientsText: 'Voor de werking van de dienst kunnen noodzakelijke technische leveranciers worden gebruikt, waaronder hosting, database, kaarten/geocodering en communicatie. Deze leveranciers mogen gegevens alleen verwerken voor zover dat noodzakelijk is voor de hun toegewezen functies.', mapData: 'Voor het zoeken naar adressen kan de TomTom Search API worden gebruikt. Kaartgegevens van de achtergrondkaart: © OpenStreetMap-bijdragers; CARTO-cartografie op basis van OpenStreetMap.', retentionTitle: 'Bewaartermijn', retentionText: 'Reserveringsgegevens worden in actieve operationele systemen bewaard totdat de rit is voltooid of geannuleerd en gedurende de korte technische periode die nodig is om de sessie af te sluiten; daarna wordt de reservering uit de operationele database verwijderd. Transactionele communicatie en technische logs van dienstverleners kunnen onder hun eigen bewaartermijnen vallen. Gegevens die wegens wettelijke verplichtingen, facturering, boekhouding, klachten of rechtsverdediging moeten worden bewaard, worden gedurende de wettelijk toepasselijke periode behouden. Technische Push-gegevens kunnen worden verwijderd wanneer ze niet meer nodig zijn of wanneer de subscription ongeldig wordt.', rightsTitle: 'Rechten', rightsText: 'De betrokkene kan, voor zover wettelijk van toepassing, via jose@79.pt verzoeken om inzage, rectificatie, wissing, beperking, bezwaar en overdraagbaarheid. De uitoefening van rechten is in de regel kosteloos. De CNPD bevestigt deze rechten en de verplichting om betrokkenen te informeren over doeleinden, gegevenscategorieën, ontvangers en bewaring.', rightsLink: 'Meer informatie bij de CNPD', privacyComplaintsTitle: 'Klachten over gegevensbescherming', privacyComplaintsText: 'Onverminderd de mogelijkheid om contact op te nemen met de verwerkingsverantwoordelijke kan de betrokkene een klacht indienen bij de', cnpdLink: 'Portugese Nationale Commissie voor Gegevensbescherming (CNPD)', pushTitle: 'Pushmeldingen', pushText: 'Pushmeldingen worden alleen geactiveerd na toestemming van de gebruiker. De technische subscription wordt uitsluitend gebruikt om reserveringsupdates te versturen en kan worden verwijderd wanneer deze niet meer geldig is.', complaintsTitle: 'Klachtenboek', complaintsIntro: 'Het elektronische Klachtenboek is beschikbaar via:', complaintsLink: 'Elektronisch Klachtenboek', complaintsLawText: 'De toepasselijke regeling verplicht betrokken dienstverleners om op hun websites toegang tot het Digitale Platform te publiceren.', complaintsLawLink: 'Wetsbesluit nr. 156/2005', ralTitle: 'Alternatieve Geschillenbeslechting', ralText: 'Voor consumentengeschillen die binnen zijn bevoegdheid vallen kan het Lissabons Arbitragecentrum voor Consumentengeschillen (CACCL) worden gebruikt wanneer aan de wettelijke voorwaarden is voldaan, waaronder consumentenovereenkomsten die in de Metropoolregio Lissabon zijn gesloten en uitgevoerd en een waarde tot € 5.000 hebben.', ralLink: 'Lissabons Arbitragecentrum voor Consumentengeschillen', ralNote: 'Het CACCL geeft ook informatie over zijn informatie- en klachtenformulieren en contactmogelijkheden.', contactsTitle: 'Contacten'
    },
    pl: {
      pageTitle: 'Informacje prawne i prywatność · 691 Lisboa', meta: 'Informacje prawne, prywatność, skargi i alternatywne rozwiązywanie sporów dla usługi 691 Lisboa.', back: '← Wróć do 691 Lisboa', legalTitle: 'Informacje prawne', updated: 'Ostatnia aktualizacja: 18 sierpnia 2026 r.', translationNote: 'Tłumaczenie służy ułatwieniu lektury. W razie rozbieżności rozstrzygająca jest wersja portugalska.', providerTitle: 'Dane usługodawcy', nifLabel: 'Numer podatkowy (NIF)', licenseLabel: 'Licencja taxi nr', phoneLabel: 'Telefon', mobileCall: 'Połączenie z portugalską krajową siecią komórkową', emailLabel: 'E-mail', bookingPriceTitle: 'Rezerwacje i cena', bookingRequest: 'Wysłanie formularza na 691.pt stanowi prośbę o rezerwację. Rezerwacja wymaga potwierdzenia przez usługę.', price: 'Cena przejazdu jest ustalana przez taksometr zgodnie z obowiązującą taryfą prawną i zasadami mającymi zastosowanie do usług taxi. Ostateczna kwota to kwota wskazana przez taksometr na końcu przejazdu, chyba że właściwe przepisy stanowią inaczej.', important: 'Ważna informacja:', priceNote: 'elektroniczne platformy usług taxi podlegają szczególnym zasadom dotyczącym udostępniania szacunkowej ceny końcowej. Automatyczna wycena w formularzu wymaga integracji właściwej taryfy oraz parametrów niezbędnych do obliczeń.', privacyTitle: 'Polityka prywatności', controller: 'Administratorem danych osobowych zbieranych przez 691.pt jest José Alfredo Mendes Fernandes.', dataTitle: 'Przetwarzane dane', dataText: 'W zależności od sposobu korzystania z usługi mogą być przetwarzane: imię i nazwisko, telefon, żądana data i godzina, miejsce odbioru, miejsce docelowe, identyfikatory techniczne niezbędne do sesji oraz informacje związane z rezerwacją.', purposesTitle: 'Cele', purpose1: 'przyjmowanie i zarządzanie prośbami o rezerwację;', purpose2: 'kontakt z klientem w sprawie rezerwacji;', purpose3: 'śledzenie statusu rezerwacji i świadczenie usługi;', purpose4: 'wypełnianie obowiązków prawnych i odpowiadanie na skargi lub uzasadnione żądania.', basisTitle: 'Podstawa prawna', basisText: 'Jeżeli przetwarzanie jest niezbędne do obsługi i realizacji żądanej usługi, podstawą prawną jest co do zasady wykonanie działań przed zawarciem umowy lub wykonanie umowy. Inne operacje przetwarzania zależą od właściwej podstawy prawnej. Zgoda nie jest używana jako uniwersalna podstawa dla przetwarzania niezbędnego do świadczenia usługi.', recipientsTitle: 'Odbiorcy i dostawcy techniczni', recipientsText: 'Do działania usługi mogą być wykorzystywani niezbędni dostawcy techniczni, w tym hosting, baza danych, mapy/geokodowanie i komunikacja. Dostawcy ci powinni przetwarzać dane wyłącznie w zakresie niezbędnym do wykonywania powierzonych im funkcji.', mapData: 'Wyszukiwanie adresów może korzystać z API TomTom Search. Dane mapy tła: © współtwórcy OpenStreetMap; kartografia CARTO oparta na OpenStreetMap.', retentionTitle: 'Przechowywanie', retentionText: 'Dane rezerwacji są przechowywane w aktywnych systemach operacyjnych do zakończenia lub anulowania przejazdu oraz przez krótki okres techniczny potrzebny do zamknięcia sesji, po czym rezerwacja jest usuwana z operacyjnej bazy danych. Komunikacja transakcyjna i techniczne dzienniki dostawców mogą podlegać ich własnym okresom przechowywania. Dane, które muszą być przechowywane ze względu na obowiązki prawne, fakturowanie, księgowość, skargi lub obronę praw, są zachowywane przez okres wymagany prawem. Techniczne dane Push mogą zostać usunięte, gdy nie są już potrzebne lub gdy subskrypcja stanie się nieważna.', rightsTitle: 'Prawa', rightsText: 'Osoba, której dane dotyczą, może — gdy ma to zastosowanie zgodnie z prawem — za pośrednictwem jose@79.pt żądać dostępu, sprostowania, usunięcia, ograniczenia, zgłosić sprzeciw i skorzystać z przenoszenia danych. Korzystanie z praw jest co do zasady bezpłatne. CNPD potwierdza te prawa oraz obowiązek informowania o celach, kategoriach danych, odbiorcach i okresach przechowywania.', rightsLink: 'Więcej informacji w CNPD', privacyComplaintsTitle: 'Skargi dotyczące ochrony danych', privacyComplaintsText: 'Niezależnie od kontaktu z administratorem osoba, której dane dotyczą, może złożyć skargę do', cnpdLink: 'Portugalskiej Krajowej Komisji Ochrony Danych (CNPD)', pushTitle: 'Powiadomienia Push', pushText: 'Powiadomienia Push są aktywowane wyłącznie po uzyskaniu zgody użytkownika. Techniczna subskrypcja służy wyłącznie do wysyłania aktualizacji dotyczących rezerwacji i może zostać usunięta, gdy przestanie być ważna.', complaintsTitle: 'Księga skarg', complaintsIntro: 'Elektroniczna Księga skarg jest dostępna pod adresem:', complaintsLink: 'Elektroniczna Księga skarg', complaintsLawText: 'Obowiązujące przepisy wymagają od objętych nimi usługodawców opublikowania na swoich stronach dostępu do Platformy Cyfrowej.', complaintsLawLink: 'Dekret z mocą ustawy nr 156/2005', ralTitle: 'Alternatywne Rozwiązywanie Sporów', ralText: 'W sporach konsumenckich należących do jego właściwości można korzystać z Lizbońskiego Centrum Arbitrażowego Sporów Konsumenckich (CACCL), gdy spełnione są warunki prawne, w tym w przypadku umów konsumenckich zawartych i wykonanych w Obszarze Metropolitalnym Lizbony o wartości do 5 000 €.', ralLink: 'Lizbońskie Centrum Arbitrażowe Sporów Konsumenckich', ralNote: 'CACCL udostępnia również informacje o formularzach informacyjnych i skargowych oraz sposobach kontaktu.', contactsTitle: 'Kontakt'
    }
  }

  function detectLanguage() {
    const requested = new URLSearchParams(window.location.search).get('lang')
    if (requested && SUPPORTED.includes(requested.toLowerCase())) return requested.toLowerCase()
    const browser = (navigator.language || 'pt').split('-')[0].toLowerCase()
    return SUPPORTED.includes(browser) ? browser : 'en'
  }

  const lang = detectLanguage()
  const t = texts[lang] || texts.en
  document.documentElement.lang = lang
  document.title = t.pageTitle
  document.getElementById('meta-description')?.setAttribute('content', t.meta)

  const mapping = {
    'back-link': 'back', 'legal-title': 'legalTitle', 'updated-text': 'updated', 'provider-title': 'providerTitle', 'nif-label': 'nifLabel', 'license-label': 'licenseLabel', 'phone-label': 'phoneLabel', 'mobile-call-text': 'mobileCall', 'email-label': 'emailLabel', 'booking-price-title': 'bookingPriceTitle', 'booking-request-text': 'bookingRequest', 'price-text': 'price', 'important-label': 'important', 'price-note-text': 'priceNote', 'privacy-title': 'privacyTitle', 'privacy-controller-text': 'controller', 'privacy-data-title': 'dataTitle', 'privacy-data-text': 'dataText', 'privacy-purposes-title': 'purposesTitle', 'purpose-1': 'purpose1', 'purpose-2': 'purpose2', 'purpose-3': 'purpose3', 'purpose-4': 'purpose4', 'privacy-basis-title': 'basisTitle', 'privacy-basis-text': 'basisText', 'privacy-recipients-title': 'recipientsTitle', 'privacy-recipients-text': 'recipientsText', 'map-data-text': 'mapData', 'privacy-retention-title': 'retentionTitle', 'privacy-retention-text': 'retentionText', 'privacy-rights-title': 'rightsTitle', 'privacy-rights-text': 'rightsText', 'privacy-rights-link': 'rightsLink', 'privacy-complaints-title': 'privacyComplaintsTitle', 'privacy-complaints-text': 'privacyComplaintsText', 'privacy-cnpd-link': 'cnpdLink', 'push-title': 'pushTitle', 'push-text': 'pushText', 'complaints-title': 'complaintsTitle', 'complaints-intro': 'complaintsIntro', 'complaints-link': 'complaintsLink', 'complaints-law-text': 'complaintsLawText', 'complaints-law-link': 'complaintsLawLink', 'ral-title': 'ralTitle', 'ral-text': 'ralText', 'ral-link': 'ralLink', 'ral-note': 'ralNote', 'contacts-title': 'contactsTitle', 'contacts-mobile-call-text': 'mobileCall', 'footer-license-label': 'licenseLabel'
  }

  for (const [id, key] of Object.entries(mapping)) {
    const node = document.getElementById(id)
    if (node && Object.prototype.hasOwnProperty.call(t, key)) node.textContent = t[key]
  }

  const note = document.getElementById('translation-note')
  if (note && lang !== 'pt' && t.translationNote) {
    note.textContent = t.translationNote
    note.hidden = false
  }

  const encodedLang = encodeURIComponent(lang)
  const back = document.getElementById('back-link')
  if (back) back.href = `/?lang=${encodedLang}`

  const complaints = document.getElementById('complaints-link')
  if (complaints) complaints.href = `https://www.livroreclamacoes.pt/Inicio/?lang=${lang === 'pt' ? 'PT' : 'EN'}`
})()
